@pytest.mark.asyncio
async def test_table_markup_cannot_hide_wrong_visible_translation(tools, run, fake):
    source = "<table>" + "<tr><td>aaaaaaaa</td></tr>" * 12 + "</table>"
    fake.translation = lambda body: body["text"].replace("aaaaaaaa", "zzzzzzzz")
    result = await tools.call("translate", {"source": input_ref(run, source), "target_language": "mr"})
    assert result["ok"] and not result["verification"]["passed"]


@pytest.mark.asyncio
async def test_batched_html_discards_active_model_markup(tools, run, fake):
    source = "<table><tr><td>Beans</td><td>18</td></tr></table>"
    fake.translation = lambda body: (
        body["text"].replace("<table>", '<table onclick="alert(1)">') + "<script>alert(1)</script>"
        if body["target_language"] == "mr" else body["text"]
    )
    result = await tools.call("translate", {"source": input_ref(run, source), "target_language": "mr"})
    assert result["ok"] and result["verification"]["passed"]
    output = run.resolve(result["ref"]).read_text()
    assert "<script" not in output and "onclick" not in output


@pytest.mark.asyncio
async def test_html_merged_cells_preserved(tools, run):
    text = '<table><tr><th colspan="2">School</th></tr><tr><td>A</td><td>B</td></tr></table>'
    result = await tools.call(
        "translate", {"source": input_ref(run, text), "target_language": "mr"}
    )
    output = run.resolve(result["ref"]).read_text()
    assert 'colspan="2"' in output and output.count("<td>") == 2


@pytest.mark.asyncio
async def test_transcribe_3_minutes_and_reuse(tools, run, fake):
    path = run.input_root / "long.wav"
    path.write_bytes(wav_bytes(180, 16000))
    ref = run.register(path, "input")
    result = await tools.call("transcribe", {"source": ref, "language": "hi"})
    assert result["ok"]
    segments = json.loads(run.resolve(result["segments_ref"]).read_text())
    assert len(segments) == 8 and segments[-1]["end"] == 180
    count = len(fake.requests)
    await tools.call("transcribe", {"source": ref, "language": "hi"})
    assert len(fake.requests) == count


@pytest.mark.asyncio
async def test_speech_chunking_voice_and_verification(tools, run, fake):
    ref = input_ref(run, "The class starts at nine. " * 20)
    result = await tools.call("synthesize", {"source": ref, "language": "bn", "format": "mp3"})
    assert result["ok"] and result["verification"]["passed"]
    assert run.resolve(result["ref"]).suffix == ".mp3"
    assert result["voice"] == "Ishita" and result["ai_generated"]
    bodies = [json.loads(r.content) for r in fake.requests if r.url.path.endswith("speech")]
    assert all(len(body["input"].encode()) <= 500 for body in bodies)
    assert len(result["verification"]["chunks"]) >= 2


@pytest.mark.asyncio
async def test_planner_english_requires_translation_before_nonenglish_speech(tools, fake):
    source = await tools.call("write_english", {"text": "The library opens on Monday."})
    result = await tools.call("synthesize", {"source": source["ref"], "language": "bn"})
    assert not result["ok"]
    assert result["error"]["code"] == "translation_required"
    assert not fake.requests
    translated = await tools.call(
        "translate", {"source": source["ref"], "target_language": "bn"}
    )
    speech = await tools.call("synthesize", {"source": translated["ref"], "language": "bn"})
    assert speech["ok"] and speech["verification"]["passed"]


@pytest.mark.asyncio
async def test_planner_english_can_be_spoken_in_english(tools):
    source = await tools.call("write_english", {"text": "The library opens on Monday."})
    result = await tools.call("synthesize", {"source": source["ref"], "language": "en"})
    assert result["ok"] and result["verification"]["passed"]


