@pytest.mark.asyncio
async def test_ocr_all_eight_pdf_pages(tools, run, fake):
    path = run.input_root / "scan.pdf"
    with pymupdf.open() as doc:
        for _ in range(8):
            page = doc.new_page()
            page.insert_text((30, 30), "Synthetic test fixture, no personal data")
        doc.save(path)
    result = await tools.call("ocr", {"source": run.register(path, "input")})
    assert result["ok"] and result["pages"] == 8
    assert len(json.loads(run.resolve(result["layout_ref"]).read_text())) == 8
    body = json.loads(fake.requests[0].content)
    assert body["messages"][0]["content"][0]["image_url"]["url"].startswith(
        "data:image/png;base64,"
    )


@pytest.mark.asyncio
async def test_image_ocr_then_table_translation(tools, run, fake):
    fake.ocr_text = "| Item | Count |\n| --- | --- |\n| Rice | 2 |"
    path = run.input_root / "sheet.png"
    Image.new("RGB", (100, 100), "white").save(path)
    ocr = await tools.call(
        "ocr", {"source": run.register(path, "input"), "table_format": "markdown"}
    )
    result = await tools.call("translate", {"source": ocr["ref"], "target_language": "mr"})
    assert result["ok"] and "| Rice | 2 |" in run.resolve(result["ref"]).read_text()


@pytest.mark.asyncio
async def test_subtitles_all_chunks_checked(tools, run):
    path = run.input_root / "note.wav"
    path.write_bytes(wav_bytes(55, 16000))
    result = await tools.call(
        "subtitles", {"source": run.register(path, "input"), "source_language": "hi"}
    )
    assert result["ok"] and result["segments"] == 3
    assert "00:00:50,000 --> 00:00:55,000" in run.resolve(result["ref"]).read_text()
    assert len(result["verification"]["checks"]) == 3


